import logging
from webhook_handler import handle_webhook

class TestWebhookHandler(unittest.TestCase):
    def test_opened(self):
        payload = {'action': 'opened', 'pull_request': {'title': 'Fix bug'}, 'repository': {'full_name': 'test/repo'}}
        with self.assertLogs(level='INFO') as cm:
            status, msg = handle_webhook(payload)
        self.assertEqual((status, msg), (200, 'ok'))
        self.assertIn('PR opened: Fix bug in test/repo', cm.output[0])

    def test_closed_merged(self):
        payload = {'action': 'closed', 'pull_request': {'merged': True}}
        with self.assertLogs(level='INFO') as cm:
            status, msg = handle_webhook(payload)
        self.assertEqual((status, msg), (200, 'ok'))
        self.assertEqual(cm.output[0], 'INFO:root:PR merged')

    def test_closed_not_merged(self):
        payload = {'action': 'closed', 'pull_request': {'merged': False}}
        with self.assertLogs(level='INFO') as cm:
            status, msg = handle_webhook(payload)
        self.assertEqual((status, msg), (200, 'ok'))
        self.assertEqual(cm.output[0], 'INFO:root:PR closed without merge')

    def test_invalid_payload(self):
        payload = {'action': 'opened'}
        status, msg = handle_webhook(payload)
        self.assertEqual((status, msg), (400, 'invalid payload'))

