package pool

import (
	"fmt"
	"sync"
)

type Job struct {
	ID   int
	Data []byte
}

type Pool struct {
	jobs    chan Job
	wg      sync.WaitGroup
	stopCh  chan struct{}
	workers int
}

func New(workers int) *Pool {
	p := &Pool{
		jobs:    make(chan Job, 10),
		stopCh:  make(chan struct{}),
		workers: workers,
	}
	return p
}

func (p *Pool) Start() {
	for i := 0; i < p.workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}
}

func (p *Pool) Submit(job Job) {
	p.jobs <- job
}

func (p *Pool) Stop() {
	close(p.jobs)
	p.wg.Wait()
}

func (p *Pool) worker() {
	defer p.wg.Done()
