void parse_tokens(char* input, int len) {
    int start = 0;
    int count = 0;
    for (int i = 0; i <= len; i++) {
        if (i == len || input[i] == ',') {
            int token_len = i - start;
            tokens[count] = (char*)malloc(token_len + 1);
            memcpy(tokens[count], input + start, token_len);
