const { getLocalUser, saveUser } = require('./db');

class UserServiceError extends Error {
  constructor(message, cause) {
    super(message);
    this.name = 'UserServiceError';
    this.cause = cause;
  }
}

async function processUser(userId) {
  try {
    let remoteUser;
    try {
      const response = await axios.get(`https://api.example.com/users/${userId}`);
      remoteUser = response.data;
    } catch (error) {
      console.error({ step: 'fetch', userId, error: error.message });
      throw new UserServiceError(`Failed to fetch user data for ${userId}`, error);
    }

    let localUser;
    try {
      localUser = await getLocalUser(userId);
    } catch (error) {
      console.error({ step: 'enrich', userId, error: error.message });
      throw new UserServiceError(`Failed to enrich user data for ${userId}`, error);
    }

    const enrichedUser = {
      ...remoteUser,
      ...localUser,
      id: userId,
      enrichedAt: new Date().toISOString()
    };

    try {
      await saveUser(enrichedUser);
    } catch (error) {
      console.error({ step: 'save', userId, error: error.message });
      throw new UserServiceError(`Failed to save user data for ${userId}`, error);
    }

    return enrichedUser;
  } catch (error) {
    if (error instanceof UserServiceError) {
      throw error;
    }
    // Unexpected error (shouldn't happen, but just in case)
    console.error({ step: 'unknown', userId, error: error.message });
    throw new UserServiceError(`Unexpected error processing user ${userId}`, error);
  }
}

module.exports = { processUser, UserServiceError };
