```javascript
class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.width = 30;
    this.height = 30;
  }
  update(input) {
    this.vx = 0;
    if (input.left) this.vx = -5;
    if (input.right) this.vx = 5;
    this.vy += 0.5;
    this.x += this.vx;
    this.y += this.vy;
  }
}

class Platform {
  constructor(x, y, width, height) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
  }
}

class Game {
  constructor() {
    this.player = new Player(50, 300);
    this.platforms = [
      new Platform(0, 500, 200, 20),
      new Platform(300, 400, 200, 20),
      new Platform(200, 250, 100, 20)
    ];
    this.coins = [
      {x: 100, y: 200, collected: false},
      {x: 250, y: 150, collected: false},
      {x: 400, y: 100, collected: false}
    ];
    this.score = 0;
    this.input = {left: false, right: false};
  }
  setInput(left, right) {
    this.input.left = left;
    this.input.right = right;
  }
  update() {
    this.player.update(this.input);
    // Collision detection
    for (let plat of this.platforms) {
      if (this.player.x < plat.x + plat.width &&
          this.player.x + this.player.width > plat.x &&
          this.player.y < plat.y + plat.height &&
          this.player.y + this.player.height > plat.y) {
        // Only align if falling
        if (this.player.vy >= 0) {
          this.player.y = plat.y - this.player.height;
          this.player.vy = 0;
        }
      }
    }
    // Coin collection
    for (let coin of this.coins) {
      if (!coin.collected &&
          Math.abs(this.player.x + this.player.width/2 - coin.x) < 25 &&
          Math.abs(this.player.y + this.player.height/2 - coin.y) < 25) {
        coin.collected = true;
        this.score += 1;
      }
    }
    // Fall off screen
    if (this.player.y > 600) {
      this.player.x = 50;
      this.player.y = 300;
      this.player.vy = 0;
      this.player.vx = 0;
      this.score = 0;
      for (let coin of this.coins) coin.collected = false;
    }
  }
}
module.exports = { Player, Platform, Game };
