  if (spacePressed) game.jump();
  game.update();

  ctx.clearRect(0, 0, 600, 600);
  // Draw platforms
  for (let plat of game.platforms) {
    ctx.fillStyle = 'blue';
    ctx.fillRect(plat.x, plat.y, plat.width, plat.height);
