function drawGrid(ctx, grid, cellSize) {
    const rows = grid.length;
    const cols = grid[0].length;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            const x = c * cellSize;
            const y = r * cellSize;
            const val = grid[r][c];
            if (val === 1) {
                ctx.fillStyle = '#333';
            } else if (val === 2) {
                ctx.fillStyle = '#4CAF50';
            } else {
                ctx.fillStyle = '#fff';
            }
            ctx.fillRect(x, y, cellSize, cellSize);
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.strokeRect(x, y, cellSize, cellSize);
        }
    }
}

function drawPlayer(ctx, player, cellSize) {
    const radius = cellSize / 3;
    const centerX = player.x * cellSize + cellSize / 2;
    const centerY = player.y * cellSize + cellSize / 2;
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
    ctx.fillStyle = '#f00';
    ctx.fill();
}

function drawHUD(ctx, score, moves) {
    ctx.font = '16px monospace';
    ctx.fillStyle = '#000';
    ctx.fillText('Score: ' + score, 10, 20);
    ctx.fillText('Moves: ' + moves, 10, 40);
}
