from datetime import datetime

def validate_parquet(file_path):
    df = pd.read_parquet(file_path)

    # Check 1: No null values
    null_cols = df.columns[df.isnull().any()].tolist()
    assert not null_cols, f"Null values found in columns: {null_cols}"

    # Check 2: order_date format
    for i, date_str in enumerate(df['order_date']):
        try:
            datetime.strptime(date_str, '%Y-%m-%d')
        except ValueError:
            raise AssertionError(f"Invalid order_date at row {i}: {date_str}")

    # Check 3: non-negative total_amount and quantity
    assert (df['total_amount'] >= 0).all(), "Negative total_amount found"
    assert (df['quantity'] >= 0).all(), "Negative quantity found"

    # Check 4: customer_id is UUID v4
    for i, cid in enumerate(df['customer_id']):
        try:
            val = uuid.UUID(cid)
            assert val.version == 4, f"customer_id at row {i} is not version 4"
        except ValueError:
            raise AssertionError(f"Invalid customer_id at row {i}: {cid}")

    print("All validation checks passed.")

if __name__ == "__main__":
    import sys
    validate_parquet(sys.argv[1] if len(sys.argv) > 1 else '/data/transformed_sales_data.parquet')
"}

