const axios = require('axios');

async function handleWeatherCommand(command_text, respond) {
  const city = command_text.trim();
  if (!city) {
    await respond({ text: 'Please provide a city name, e.g. /weather San Francisco' });
    return;
  }
  await respond({ text: `Fetching weather for ${city}...` });
  try {
    const apiKey = process.env.OPENWEATHER_API_KEY;
    const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&appid=${apiKey}&units=metric`;
    const response = await axios.get(url);
    const temp = response.data.main.temp;
    const desc = response.data.weather[0].description;
    await respond({ text: `The weather in ${city} is ${temp}°C and ${desc}.` });
  } catch (error) {
    await respond({ text: `Could not fetch weather for ${city}. Please check the city name.` });
  }
}

module.exports = { handleWeatherCommand };
