{"file_path": "validate_data.py", "content": "import pandas as pd
import sys

df = pd.read_csv('processed_customers.csv')
print(f'Total rows: {len(df)}')

# Check missing values
missing = df.isnull().mean() * 100
for col, pct in missing.items():
    if pct > 5:
        print(f'WARNING: Column {col} has {pct:.2f}% missing values')

# Check constraints
violations = []
for idx, row in df.iterrows():
    problems = []
    if not (18 <= row['age'] <= 100):
        problems.append(f'age={row["age"]}')
    if not (0 <= row['tenure_months'] <= 72):
        problems.append(f'tenure_months={row["tenure_months"]}')
    if not (0 <= row['monthly_charges'] <= 2000):
        problems.append(f'monthly_charges={row["monthly_charges"]}')
    if row['churn'] not in [0, 1]:
        problems.append(f'churn={row["churn"]}')
    if problems:
        violations.append((idx, problems))

if violations:
    print(f'Found {len(violations)} violating rows:')
    for idx, probs in violations[:10]:
        print(f'  Row {idx}: {", ".join(probs)}')
    if len(violations) > 10:
        print(f'  ... and {len(violations)-10} more')
    sys.exit(1)
else:
    print('ALL CHECKS PASSED')
"}

{"file_path": "/app/webhook_handler.py", "content": """
Webhook handler for payment events.
This module processes incoming webhooks from Stripe-like payment provider.

"""
import logging
from flask import request, jsonify
from db import record_payment

app = None  # Will be set by the main app

@app.route('/webhook', methods=['POST'])
def handle_webhook():
    """Process incoming webhook payloads."""
    try:
        data = request.get_json()
    except Exception:
        return jsonify({'error': 'Invalid JSON'}), 400

    event_type = data.get('type')
    if event_type == 'checkout.session.completed':
        session = data.get('data', {}).get('object', {})
        email = session.get('customer_email')
        amount_cents = session.get('amount_total')
        if email and amount_cents:
            record_payment(email, amount_cents)
        else:
            logging.error('Missing email or amount in checkout.session.completed')
        return jsonify({'received': True})
    elif event_type == 'payment_intent.payment_failed':
        intent = data.get('data', {}).get('object', {})
        email = intent.get('receipt_email')
        reason = intent.get('last_payment_error', {}).get('message', 'Unknown')
        logging.error(f'Payment failed for {email}: {reason}')
        return jsonify({'received': True})
    else:
        return jsonify({'received': False, 'message': 'Event ignored'}), 200
"""}

